# backend/app/goals/router.py
import uuid

from fastapi import APIRouter, Depends, HTTPException, Query, status
from sqlalchemy.ext.asyncio import AsyncSession

from app.auth.deps import get_current_user, require_manager, require_rep
from app.auth.models import User
from app.db import get_db
from app.goals.schemas import GoalCreate, GoalLogValue, GoalOut, GoalProgress
from app.goals.service import (
    GoalNotFoundError,
    MetricNotManualError,
    create_goal,
    get_goal,
    get_goal_progress,
    list_goals,
    log_value,
)
from app.zones.service import RepNotFoundError

router = APIRouter(prefix="/api/v1/goals", tags=["goals"])


@router.post("", response_model=GoalOut, status_code=status.HTTP_201_CREATED)
async def create_goal_endpoint(
    body: GoalCreate,
    current_user: User = Depends(require_manager),
    db: AsyncSession = Depends(get_db),
) -> GoalOut:
    try:
        return await create_goal(
            db,
            tenant_id=current_user.tenant_id,
            rep_id=body.rep_id,
            metric_type=body.metric_type,
            target=body.target,
            period_start=body.period_start,
            period_end=body.period_end,
        )
    except RepNotFoundError as exc:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="rep not found") from exc


@router.get("", response_model=list[GoalOut])
async def list_goals_endpoint(
    limit: int = Query(50, ge=1, le=200),
    offset: int = Query(0, ge=0),
    current_user: User = Depends(get_current_user),
    db: AsyncSession = Depends(get_db),
) -> list[GoalOut]:
    return await list_goals(db, current_user, limit=limit, offset=offset)


@router.get("/{goal_id}", response_model=GoalOut)
async def get_goal_endpoint(
    goal_id: uuid.UUID,
    current_user: User = Depends(get_current_user),
    db: AsyncSession = Depends(get_db),
) -> GoalOut:
    goal = await get_goal(db, current_user, goal_id)
    if goal is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="goal not found")
    return goal


@router.get("/{goal_id}/progress", response_model=GoalProgress)
async def get_goal_progress_endpoint(
    goal_id: uuid.UUID,
    current_user: User = Depends(get_current_user),
    db: AsyncSession = Depends(get_db),
) -> GoalProgress:
    progress = await get_goal_progress(db, current_user, goal_id)
    if progress is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="goal not found")
    return progress


@router.post("/{goal_id}/log-value", response_model=GoalOut)
async def log_value_endpoint(
    goal_id: uuid.UUID,
    body: GoalLogValue,
    current_user: User = Depends(require_rep),
    db: AsyncSession = Depends(get_db),
) -> GoalOut:
    try:
        return await log_value(
            db, tenant_id=current_user.tenant_id, rep_id=current_user.id, goal_id=goal_id, value=body.value
        )
    except GoalNotFoundError as exc:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="goal not found") from exc
    except MetricNotManualError as exc:
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT, detail="goal metric is not manually logged"
        ) from exc

import contextvars
import uuid

from sqlalchemy import event
from sqlalchemy.orm import Mapped, Session, mapped_column, with_loader_criteria

current_tenant_id: contextvars.ContextVar[uuid.UUID | None] = contextvars.ContextVar(
    "current_tenant_id", default=None
)


class TenantScopedMixin:
    tenant_id: Mapped[uuid.UUID] = mapped_column(nullable=False, index=True)


_installed = False


def install_tenancy_filter() -> None:
    """Registers a global SELECT/UPDATE/DELETE filter scoping every TenantScopedMixin query
    to current_tenant_id. Idempotent — safe to call more than once (e.g. once
    per test)."""
    global _installed
    if _installed:
        return

    @event.listens_for(Session, "do_orm_execute")
    def _apply_tenant_filter(execute_state):
        # Apply tenant filter to SELECT, UPDATE, and DELETE statements
        if not (execute_state.is_select or execute_state.is_update or execute_state.is_delete):
            return
        tenant_id = current_tenant_id.get()
        if tenant_id is None:
            return
        execute_state.statement = execute_state.statement.options(
            with_loader_criteria(
                TenantScopedMixin,
                lambda cls: cls.tenant_id == tenant_id,
                include_aliases=True,
            )
        )

    _installed = True
